def rotationRank(s):
    n = len(s)
    d = s + s
    t = s + '#' + d
    m = len(t)
    z = [0] * m
    l = r = 0
    for i in range(1, m):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < m and t[z[i]] == t[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    lcp = [z[n + 1 + i] for i in range(n)]
    period = n
    for i in range(1, n):
        if lcp[i] >= n:
            period = i
            break
    count = 0
    for i in range(1, period):
        if d[i + lcp[i]] < s[lcp[i]]:
            count += 1
    return count
